class Solution {
public:
    ListNode* partition(ListNode* head, int x) {
        ListNode* low = new ListNode(0);
        ListNode* high = new ListNode(0);
        ListNode* lowTail = low;
        ListNode* highTail = high;
        while (head) {
            if (head->val < x) {
                lowTail->next = head;
                lowTail = head;
            } else {
                highTail->next = head;
                highTail = head;
            }
            head = head->next;
        }
        highTail->next = nullptr;
        lowTail->next = high->next;
        return low->next;
    }
};
